template<typename T> class std::unique_ptr {
public:
    explicit unique_ptr(T* ptr = nullptr) noexcept;
    ~unique_ptr();
    unique_ptr(const unique_ptr&) = delete;
    unique_ptr& operator=(const unique_ptr&) = delete;
    unique_ptr(unique_ptr&&) noexcept;
    unique_ptr& operator=(unique_ptr&&) noexcept;
    T* get() const noexcept;
    T& operator*() const; 
    T* operator->() const;
    void reset(T* ptr = nullptr); 
    T* release();
};

template<typename T> class std::shared_ptr {
public:
    explicit shared_ptr(T* ptr = nullptr); 
    ~shared_ptr();
    shared_ptr(const shared_ptr&); 
    shared_ptr& operator=(const shared_ptr&); 
    T* get() const noexcept;
    T& operator*() const; 
    T* operator->() const;
    void reset(T* ptr = nullptr); 
    long use_count() const noexcept;
};

code_example:
#include <iostream>
#include <memory>

class Resource {
public:
    Resource() { std::cout << "Resource acquired" << std::endl; }
    ~Resource() { std::cout << "Resource destroyed" << std::endl; }
    void do_something() { std::cout << "Doing something" << std::endl; }
};

int main() {
    {
        auto ptr1 = std::make_unique<Resource>(); // unique_ptr manages Resource
        ptr1->do_something();
    } // Resource is automatically destroyed here when ptr1 goes out of scope

    {
        auto ptr2 = std::make_shared<Resource>(); // shared_ptr manages Resource
        auto ptr3 = ptr2; // shared ownership
        ptr2->do_something();
        std::cout << "Shared pointers count: " << ptr2.use_count() << std::endl;
    } // Resource destroyed when last shared_ptr (ptr3) goes out of scope
    return 0;
}
